let offset = 3;
let add = $[offset](x) { x + offset };

let point = @{
    let x = 1;
    let y = 2;
};

std.print(add(39));
std.print(point.x + point.y);

// 两者是同一种结构：有没有代码入口
std.print(std.inspect.describe(add).kind);
std.print(std.inspect.describe(point).kind);

let amount = 200;
let snapshot = $[amount]() { amount };
let shared = $[&amount]() { amount };
amount = 300;
std.print(snapshot());
std.print(shared());

let s = std.get(std.inspect.captures(snapshot), 0);
let r = std.get(std.inspect.captures(shared), 0);
std.print(s.mode + " → 槽 #" + std.str(s.slot_id));
std.print(r.mode + " → 槽 #" + std.str(r.slot_id));

let Accumulator = $[]() {
    @{
        let total = 0;
        let add = $[&total](amount) {
            total = total + amount;
        };
        let read = $[&total]() { total };
    }
};
let orders = Accumulator();
orders.add(200);
orders.add(300);
std.print(orders.read());

// 摊开这个对象：字段各占一个槽
let fields = std.inspect.members(orders);
let i = 0;
loop {
    if i == std.len(fields) { break; };
    let m = std.get(fields, i);
    std.print(m.name + " → 槽 #" + std.str(m.slot_id));
    i = i + 1;
};

// add 与 read 捕获的，正是 total 那个槽
let a = std.get(std.inspect.captures(orders.add), 0);
let r = std.get(std.inspect.captures(orders.read), 0);
std.print("add  捕获 total → 槽 #" + std.str(a.slot_id));
std.print("read 捕获 total → 槽 #" + std.str(r.slot_id));

let make = $[]() {
    let total = 0;
    $[&total](amount) {
        total = total + amount;
        total
    }
};
let add = make();
std.gc.collect();
std.print(add(200));
std.print(add(300));

let held = std.get(std.inspect.captures(add), 0);
std.print("total 仍在槽 #" + std.str(held.slot_id));

let total = 0;
let add = $[&total](amount) {
    total = total + amount;
};
let native = jit(add);
std.print(std.inspect.jit(native).state);
native(200);
add(300);
std.print(total);
std.print(std.inspect.jit(native).state);

let a = std.get(std.inspect.captures(add), 0);
let n = std.get(std.inspect.captures(native), 0);
std.print(a.slot_id == n.slot_id);

let square = @jit $[](x) { x * x };
